// Серверная проверка заявки: данным из браузера не доверяем,
// клиентскую валидацию можно обойти прямым запросом к вебхуку.
const input = $input.first().json;
const body = input.body ?? {};
// Канал задаёт узел «Диалог бота» на верхнем уровне; у заявки с сайта там заголовки вебхука, а body — от браузера
const fromBot = input.channel === 'telegram';
const TZ = 'Europe/Moscow';
// Режим работы из регламента: день недели (0 — вс) → [открытие, закрытие]. Совпадает с content/site.json
const SCHEDULE = { 1: [9, 19], 2: [9, 19], 3: [9, 19], 4: [9, 19], 5: [9, 19], 6: [10, 17] };

// Убираем управляющие символы и лишние пробелы, ограничиваем длину
const clean = (value, max) => String(value ?? '')
  .replace(/[\u0000-\u001F\u007F]+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, max);

const lead = {
  name: clean(body.name, 60),
  phone: clean(body.phone, 20).replace(/[^\d+]/g, ''),
  car: clean(body.car, 60),
  service: clean(body.service, 80),
  problem: clean(body.problem, 500),
};

// Столбец «Источник»: бот — telegram, сайт — utm_source из ссылки, без метки — web
const source = fromBot ? 'telegram' : (clean(body.source, 40).toLowerCase().replace(/[^a-z0-9_.-]/g, '') || 'web');

const errors = [];
if (lead.name.length < 2 || !/^[\p{L}\s'-]+$/u.test(lead.name)) errors.push('name');
if (!/^\+7\d{10}$/.test(lead.phone)) errors.push('phone');
if (body.consent !== true) errors.push('consent');

// Желаемый визит: рабочий день с сегодняшнего (по Москве) и не дальше 60 дней, время — в часы работы этого дня
const visitDate = clean(body.visitDate, 10);
const visitTime = clean(body.visitTime, 5);
let visit = '';
if (visitDate) {
  const today = new Date().toLocaleDateString('en-CA', { timeZone: TZ });
  const [y, m, d] = today.split('-').map(Number);
  const maxDate = new Date(Date.UTC(y, m - 1, d + 60)).toISOString().slice(0, 10);
  const parsed = /^\d{4}-\d{2}-\d{2}$/.test(visitDate) ? new Date(`${visitDate}T00:00:00Z`) : null;
  const isRealDate = parsed && !Number.isNaN(parsed.getTime()) && parsed.toISOString().slice(0, 10) === visitDate;
  const hours = isRealDate ? SCHEDULE[parsed.getUTCDay()] : null; // воскресенье — выходной
  const hour = Number(visitTime.slice(0, 2));
  const isTimeOk = !visitTime || (/^\d{2}:00$/.test(visitTime) && hours && hour >= hours[0] && hour < hours[1]);

  if (!isRealDate || !hours || visitDate < today || visitDate > maxDate || !isTimeOk) {
    errors.push('visit');
  } else {
    const [vy, vm, vd] = visitDate.split('-');
    visit = `${vd}.${vm}.${vy}${visitTime ? ` ${visitTime}` : ', время любое'}`;
  }
} else if (visitTime) {
  errors.push('visit');
}

const receivedAt = new Date().toLocaleString('ru-RU', { timeZone: TZ });

// Текст для Telegram собираем здесь, а не выражением в узле Telegram: так его можно проверить как обычный JS
const telegramText = [
  fromBot ? 'Новая заявка из Telegram-бота' : 'Новая заявка с сайта',
  ...(fromBot ? [`Telegram: ${clean(body.telegram, 40) || 'без username'}`] : []),
  `Имя: ${lead.name}`,
  `Телефон: ${lead.phone}`,
  `Услуга: ${lead.service || '—'}`,
  `Запись: ${visit || 'не выбрана'}`,
  `Марка: ${lead.car || '—'}`,
  `Что случилось: ${lead.problem || '—'}`,
  `Источник: ${source}`,
  `Получена: ${receivedAt}`,
].join('\n');

return [{
  json: {
    ok: errors.length === 0,
    error: errors.length ? `Некорректные поля: ${errors.join(', ')}` : '',
    ...lead,
    visit,
    // Время сервера, а не браузера: часы клиента могут врать
    receivedAt,
    telegramText,
    status: 'Новая',
    source,
    channel: fromBot ? 'telegram' : 'site',
    chatId: fromBot ? String(input.chatId) : '',
  },
}];

// Диалог клиентского бота: те же поля и порядок, что в форме на /zapis/.
// Состояние чатов — в static data воркфлоу: сохраняется только у активного воркфлоу (не в ручном тесте).
const SITE_URL = 'https://quillonlending.vercel.app'; // = content/site.json → url
const PRIVACY_URL = `${SITE_URL}/privacy.html`;
// Названия услуг по порядку — как в content/services (title по order). Сборка сверяет списки
const SERVICES = ["ТО", "Тормоза", "Ремень ГРМ", "Диагностика", "Кондиционер", "Шиномонтаж"];
const NO_SERVICE = 'Не знаю, нужна консультация';
// Режим работы: день недели (0 — вс) → [открытие, закрытие]. Совпадает с content/site.json и «Проверкой и очисткой»
const SCHEDULE = { 1: [9, 19], 2: [9, 19], 3: [9, 19], 4: [9, 19], 5: [9, 19], 6: [10, 17] };
const DAYS_AHEAD = 14; // = content/site.json → booking.daysAhead
const DATE_BUTTONS = 6;
const MIN_LEAD_MINUTES = 60;
const RATE_LIMIT_MS = 60 * 1000;
const SESSION_TTL_MS = 24 * 60 * 60 * 1000;
const TZ = 'Europe/Moscow';

const BTN = {
  consent: 'Согласен',
  phone: 'Отправить мой номер',
  anyDay: 'Любой день',
  anyTime: 'Любое время',
  skip: 'Пропустить',
  send: 'Отправить заявку',
  restart: 'Начать заново',
};

const update = $input.first().json;
const message = update.message;
// Пишем только в личные чаты; служебные обновления пропускаем
if (!message || !message.chat || message.chat.type !== 'private') return [];

const chatId = String(message.chat.id);
const store = $getWorkflowStaticData('global');
store.sessions = store.sessions || {};
store.lastLead = store.lastLead || {};
const nowMs = Date.now();

// Старые незавершённые диалоги удаляем: там персональные данные, хранить их незачем
for (const [id, s] of Object.entries(store.sessions)) {
  if (nowMs - s.updatedAt > SESSION_TTL_MS) delete store.sessions[id];
}
for (const [id, at] of Object.entries(store.lastLead)) {
  if (nowMs - at > RATE_LIMIT_MS) delete store.lastLead[id];
}

const clean = (value, max) => String(value ?? '')
  .replace(/[\u0000-\u001F\u007F]+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, max);

const text = clean(message.text, 600);
const pad = (n) => String(n).padStart(2, '0');

function moscowNow() {
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
  }).formatToParts(new Date(nowMs));
  const get = (type) => Number(parts.find((part) => part.type === type).value);
  return { year: get('year'), month: get('month'), day: get('day'), minutes: get('hour') * 60 + get('minute') };
}

const dayLabel = new Intl.DateTimeFormat('ru-RU', { timeZone: 'UTC', weekday: 'short', day: 'numeric', month: 'long' });

// Те же дни и часы, что предлагает форма на сайте: последний слот за час до закрытия, сегодня — с запасом в час
function bookingDays() {
  const now = moscowNow();
  const days = [];
  for (let offset = 0; offset <= DAYS_AHEAD; offset += 1) {
    const date = new Date(Date.UTC(now.year, now.month - 1, now.day + offset));
    const hours = SCHEDULE[date.getUTCDay()];
    const slots = [];
    if (hours) {
      for (let hour = hours[0]; hour < hours[1]; hour += 1) {
        if (offset > 0 || hour * 60 >= now.minutes + MIN_LEAD_MINUTES) slots.push(`${pad(hour)}:00`);
      }
    }
    if (slots.length) {
      const prefix = ['Сегодня, ', 'Завтра, '][offset] || '';
      days.push({ value: date.toISOString().slice(0, 10), label: prefix + dayLabel.format(date), slots });
    }
  }
  return days;
}

// Номер из кнопки «Отправить мой номер» или набранный руками → +7XXXXXXXXXX
function normalizePhone() {
  const raw = message.contact ? message.contact.phone_number : text;
  let digits = String(raw ?? '').replace(/\D/g, '');
  if (digits.length === 11 && /^[78]/.test(digits)) digits = digits.slice(1);
  return /^\d{10}$/.test(digits) ? `+7${digits}` : '';
}

// Дата, набранная руками: 05.11 или 05.11.2026
function findTypedDay(days) {
  const match = /^(\d{1,2})[./](\d{1,2})(?:[./](\d{4}))?$/.exec(text);
  if (!match) return null;
  const [, d, m, y] = match;
  return days.find(({ value }) => value.endsWith(`-${pad(m)}-${pad(d)}`) && (!y || value.startsWith(y))) || null;
}

const reply = (session, body, keyboard = 'none', buttons = []) => {
  if (session) {
    session.updatedAt = nowMs;
    store.sessions[chatId] = session;
  }
  return [{ json: { done: false, chatId, text: body, keyboard, buttons } }];
};

const visitText = (data) => {
  if (!data.visitDate) return 'любой день';
  const [y, m, d] = data.visitDate.split('-');
  return `${d}.${m}.${y}${data.visitTime ? ` ${data.visitTime}` : ', время любое'}`;
};

const ask = {
  consent: (s) => reply(s, [
    'Здравствуйте! Это запись в автосервис «Шестерёнка».',
    'Данные получает автосервис «Шестерёнка», чтобы перезвонить по заявке и записать на обслуживание.',
    `Политика конфиденциальности: ${PRIVACY_URL}`,
    `Нажмите «${BTN.consent}», если согласны на обработку персональных данных в соответствии с политикой конфиденциальности.`,
  ].join('\n\n'), 'one', [BTN.consent]),
  name: (s) => reply(s, 'Как к вам обращаться?'),
  phone: (s) => reply(s, `Ваш телефон: нажмите «${BTN.phone}» или напишите номер в формате +7 XXX XXX-XX-XX.`, 'phone', [BTN.phone]),
  service: (s) => reply(s, 'Какая услуга нужна?', 'seven', [...SERVICES, NO_SERVICE]),
  date: (s) => {
    const days = bookingDays();
    const hint = 'Когда удобно приехать? Выберите день или напишите дату, например 05.11. '
      + 'Это предварительная запись: время подтвердим по телефону.';
    if (days.length < DATE_BUTTONS) return reply(s, hint, 'one', [BTN.anyDay]);
    return reply(s, hint, 'seven', [...days.slice(0, DATE_BUTTONS).map(({ label }) => label), BTN.anyDay]);
  },
  time: (s, slots) => reply(s, `Во сколько? Можно: ${slots.join(', ')}. Напишите час, например ${Number(slots[0].slice(0, 2))}.`,
    'one', [BTN.anyTime]),
  car: (s) => reply(s, 'Марка и модель — например, Kia Rio 2018.', 'one', [BTN.skip]),
  problem: (s) => reply(s, 'Что случилось — например, стучит спереди справа на кочках.', 'one', [BTN.skip]),
  confirm: (s) => reply(s, [
    'Проверьте заявку:',
    `Имя: ${s.data.name}`,
    `Телефон: ${s.data.phone}`,
    `Услуга: ${s.data.service || NO_SERVICE}`,
    `Когда: ${visitText(s.data)}`,
    `Марка: ${s.data.car || '—'}`,
    `Что случилось: ${s.data.problem || '—'}`,
  ].join('\n'), 'two', [BTN.send, BTN.restart]),
};

const start = () => ask.consent({ step: 'consent', data: {} });

let session = store.sessions[chatId];
if (!session || text === '/start' || text === BTN.restart) return start();

const steps = {
  consent() {
    if (text.toLowerCase() !== BTN.consent.toLowerCase()) return ask.consent(session);
    session.data.consent = true;
    session.step = 'name';
    return ask.name(session);
  },
  name() {
    const name = clean(text, 60);
    if (name.length < 2 || !/^[\p{L}\s'-]+$/u.test(name)) {
      return reply(session, 'Напишите имя буквами, например Иван.');
    }
    session.data.name = name;
    session.step = 'phone';
    return ask.phone(session);
  },
  phone() {
    const phone = normalizePhone();
    if (!phone) return reply(session, 'Не получилось распознать номер. Напишите его в формате +7 XXX XXX-XX-XX.', 'phone', [BTN.phone]);
    session.data.phone = phone;
    session.step = 'service';
    return ask.service(session);
  },
  service() {
    if (text !== NO_SERVICE && !SERVICES.includes(text)) return ask.service(session);
    session.data.service = text === NO_SERVICE ? '' : text;
    session.step = 'date';
    return ask.date(session);
  },
  date() {
    if (text === BTN.anyDay) {
      session.data.visitDate = '';
      session.data.visitTime = '';
      session.step = 'car';
      return ask.car(session);
    }
    const days = bookingDays();
    const day = days.find(({ label }) => label === text) || findTypedDay(days);
    if (!day) {
      return reply(session, `На этот день записи нет. Выберите день кнопкой или напишите дату в ближайшие ${DAYS_AHEAD} дней, кроме выходных.`,
        'one', [BTN.anyDay]);
    }
    session.data.visitDate = day.value;
    session.step = 'time';
    return ask.time(session, day.slots);
  },
  time() {
    const day = bookingDays().find(({ value }) => value === session.data.visitDate);
    if (!day) {
      session.step = 'date';
      return ask.date(session);
    }
    if (text === BTN.anyTime) {
      session.data.visitTime = '';
    } else {
      const match = /^(\d{1,2})(?:[:.]00)?$/.exec(text);
      const slot = match ? `${pad(match[1])}:00` : '';
      if (!day.slots.includes(slot)) return ask.time(session, day.slots);
      session.data.visitTime = slot;
    }
    session.step = 'car';
    return ask.car(session);
  },
  car() {
    session.data.car = text === BTN.skip ? '' : clean(text, 60);
    session.step = 'problem';
    return ask.problem(session);
  },
  problem() {
    session.data.problem = text === BTN.skip ? '' : clean(text, 500);
    session.step = 'confirm';
    return ask.confirm(session);
  },
  confirm() {
    if (text !== BTN.send) return ask.confirm(session);
    if (store.lastLead[chatId] && nowMs - store.lastLead[chatId] < RATE_LIMIT_MS) {
      return reply(session, 'Заявка уже отправлена. Повторить можно через минуту.', 'two', [BTN.send, BTN.restart]);
    }
    // Пока клиент заполнял, выбранное время могло пройти
    const { visitDate, visitTime } = session.data;
    const day = visitDate && bookingDays().find(({ value }) => value === visitDate);
    if (visitDate && (!day || (visitTime && !day.slots.includes(visitTime)))) {
      session.step = 'date';
      return reply(session, 'Выбранное время уже прошло — выберите другое.', 'one', [BTN.anyDay]);
    }
    delete store.sessions[chatId];
    store.lastLead[chatId] = nowMs;
    const username = message.from && message.from.username ? `@${message.from.username}` : '';
    return [{
      json: {
        done: true,
        // Признак канала — вне body: в заявке с сайта body задаёт браузер, а этот уровень — нет
        channel: 'telegram',
        chatId,
        body: { ...session.data, visitDate: visitDate || '', visitTime: visitTime || '', telegram: username },
      },
    }];
  },
};

return (steps[session.step] || start)();
